*{box-sizing:border-box} :root{--bg:#101510;--panel:#171d18;--panel2:#1d251f;--line:#2a342c;--muted:#93a095;--text:#f1f5ef;--green:#b7f36b;--green2:#89ca46;--orange:#f5a66c;--red:#ed7777;--blue:#8eb6ff} body{margin:0;background:var(--bg);color:var(--text);font:14px 'DM Sans',sans-serif;min-height:100vh}button,select{font:inherit}button{cursor:pointer} .app-shell{max-width:1440px;margin:auto;min-height:100vh;display:grid;grid-template-columns:238px minmax(0,1fr)}.sidebar{background:#131914;border-right:1px solid var(--line);padding:26px 16px;display:flex;flex-direction:column;position:sticky;top:0;height:100vh}.brand{display:flex;align-items:center;gap:11px;padding:0 12px 30px}.brand-mark{width:34px;height:34px;border-radius:11px;background:var(--green);display:grid;place-items:center;color:#17220f;font-size:19px;font-weight:700}.brand-name{font:700 19px 'Space Grotesk';letter-spacing:-.7px}.brand-name span{color:var(--green)}.side-label{color:#718074;text-transform:uppercase;letter-spacing:1.4px;font-size:10px;font-weight:700;padding:10px 12px}.nav{display:grid;gap:5px}.nav button{border:0;background:transparent;color:#9da99f;text-align:left;border-radius:9px;padding:11px 12px;display:flex;align-items:center;gap:12px;font-weight:600;transition:.18s}.nav button:hover,.nav button.active{background:#242d25;color:var(--text)}.nav button.active{box-shadow:inset 3px 0 var(--green)}.nav-icon{width:19px;text-align:center;font-size:16px}.side-bottom{margin-top:auto}.club-mini{border:1px solid var(--line);border-radius:12px;padding:13px;margin:12px 4px 8px;background:#171e18}.club-mini-top{display:flex;gap:10px;align-items:center}.club-badge{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:#26312a;font-weight:700;font-size:18px;color:var(--green)}.club-mini strong{display:block;font-size:13px}.club-mini small{color:var(--muted);font-size:11px}.main{min-width:0;padding:27px 38px 55px}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:27px;gap:18px}.eyebrow{color:var(--muted);font-size:12px}.topbar h1{font:600 25px 'Space Grotesk';margin:3px 0 0;letter-spacing:-.7px}.top-actions{display:flex;align-items:center;gap:10px}.season-pill,.icon-btn{height:38px;border:1px solid var(--line);background:var(--panel);border-radius:9px;color:#cad3ca;padding:0 12px}.season-pill{font-weight:600;font-size:12px}.icon-btn{width:38px;padding:0;font-size:16px}.avatar{height:36px;width:36px;border-radius:50%;display:grid;place-items:center;background:#394936;color:var(--green);font-weight:700}.view{display:none}.view.active{display:block}.grid{display:grid;gap:17px}.overview-grid{grid-template-columns:minmax(0,1.7fr) minmax(260px,.9fr)}.card{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:19px}.hero-card{min-height:234px;padding:23px;background:linear-gradient(112deg,#253324 0%,#1d291f 55%,#263d25 100%);position:relative;overflow:hidden}.hero-card:after{content:'⚽';position:absolute;right:35px;top:20px;font-size:130px;opacity:.055;transform:rotate(-18deg)}.hero-head{display:flex;justify-content:space-between;align-items:flex-start;position:relative;z-index:1}.club-overline,.card-label{font-size:10px;text-transform:uppercase;letter-spacing:1.35px;font-weight:700;color:#a8b7a5}.club-title{font:700 24px 'Space Grotesk';margin:7px 0 2px;letter-spacing:-.8px}.club-subtitle{font-size:12px;color:#b4c0b3}.rank-chip{border:1px solid #536449;color:#daf4be;background:#253923;border-radius:20px;padding:6px 10px;font-size:11px;font-weight:700}.hero-stats{display:flex;gap:35px;margin-top:27px;position:relative;z-index:1}.hero-stat small{display:block;color:#a8b7a5;font-size:11px;margin-bottom:4px}.hero-stat strong{font:600 20px 'Space Grotesk'}.hero-stat strong em{font-style:normal;color:var(--green);font-size:12px}.card-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.card-heading h2{font:600 14px 'Space Grotesk';margin:0}.text-btn{border:0;background:none;color:var(--green);font-weight:700;font-size:11px;padding:4px}.fixture-card{display:flex;flex-direction:column;justify-content:space-between}.fixture-type{color:var(--green);font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase}.fixture-teams{display:flex;align-items:center;justify-content:space-between;margin:19px 0 16px}.team-side{text-align:center;width:34%}.team-crest{font-size:30px;display:block;margin-bottom:6px}.team-side strong{font-size:12px}.vs{color:#7d8a7e;font-size:11px;font-weight:700}.fixture-meta{border-top:1px solid var(--line);padding-top:12px;display:flex;justify-content:space-between;color:var(--muted);font-size:11px}.primary-btn,.secondary-btn,.green-btn{border:0;border-radius:8px;font-weight:700;transition:.16s}.primary-btn{background:var(--green);color:#182116;padding:11px 15px}.primary-btn:hover,.green-btn:hover{background:#c9ff87;transform:translateY(-1px)}.fixture-card .primary-btn{width:100%;margin-top:14px}.lower-grid{grid-template-columns:minmax(0,1.4fr) minmax(250px,.8fr);margin-top:17px}.table{width:100%;border-collapse:collapse;text-align:left}.table th{color:#829084;font-size:10px;text-transform:uppercase;letter-spacing:.8px;font-weight:700;padding:8px 7px;border-bottom:1px solid var(--line)}.table td{padding:10px 7px;border-bottom:1px solid #252e27;font-size:12px}.table tr:last-child td{border-bottom:0}.table .you-row{background:#222d23}.table .you-row td:first-child{border-left:2px solid var(--green)}.pos{color:#778479;width:20px}.club-cell{font-weight:600;display:flex;align-items:center;gap:8px}.mini-crest{width:22px;height:22px;border-radius:7px;display:grid;place-items:center;background:#29362b;font-size:12px}.points{font-weight:700}.form-dots{display:flex;gap:3px}.dot{width:15px;height:15px;border-radius:50%;font-size:9px;display:grid;place-items:center;font-weight:700}.dot.W{background:#2d462e;color:var(--green)}.dot.D{background:#3a3b2b;color:#e5d077}.dot.L{background:#482d2d;color:#f39191}.activity-list{display:grid;gap:12px}.activity{display:flex;gap:10px;align-items:flex-start}.activity-icon{width:29px;height:29px;border-radius:9px;background:#253126;display:grid;place-items:center;color:var(--green);flex:none}.activity-text{font-size:11px;line-height:1.55;color:#b6c0b6}.activity-text strong{color:var(--text)}.activity-text small{display:block;color:#78857a;font-size:10px;margin-top:2px}.view-toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:17px;gap:12px}.view-toolbar h2{font:600 17px 'Space Grotesk';margin:0}.secondary-btn{background:var(--panel2);border:1px solid var(--line);color:#d7dfd7;padding:9px 13px}.secondary-btn:hover{border-color:#61775c}.section-grid{grid-template-columns:minmax(0,1fr) 300px;align-items:start}.squad-list{display:grid;gap:8px}.player-row{display:grid;grid-template-columns:38px minmax(120px,1fr) 43px 64px 78px;gap:12px;align-items:center;background:#1a211b;border:1px solid #273129;padding:11px 13px;border-radius:10px}.player-avatar{height:35px;width:35px;border-radius:10px;display:grid;place-items:center;background:#2c372e;font-weight:700;color:#d4e5cf}.player-name{font-weight:700;font-size:12px}.player-meta{font-size:10px;color:var(--muted);margin-top:3px}.rating{color:var(--green);font-weight:700}.player-value{color:#a7b3a8;font-size:11px;text-align:right}.position-label{font-size:10px;color:#8f9b90}.tag{display:inline-block;padding:4px 7px;border-radius:12px;background:#283629;color:#b8d7a2;font-size:10px;font-weight:700}.market-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.market-card{padding:16px}.market-person{display:flex;align-items:center;gap:12px;margin-bottom:14px}.market-face{width:47px;height:47px;border-radius:14px;background:linear-gradient(135deg,#405545,#253329);display:grid;place-items:center;font-size:22px}.market-name{font-weight:700}.market-info{color:var(--muted);font-size:11px;margin-top:4px}.market-stats{display:flex;justify-content:space-between;padding:11px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-bottom:12px;color:#aab5ab;font-size:11px}.market-stats strong{color:var(--text)}.market-card .primary-btn{width:100%;padding:9px}.market-card .primary-btn:disabled{background:#344136;color:#8f9b90;cursor:default}.filter-tabs{display:flex;gap:6px;flex-wrap:wrap}.filter-tabs button{border:1px solid var(--line);background:var(--panel);border-radius:20px;color:#99a59a;font-size:11px;padding:7px 11px}.filter-tabs button.active{background:#2d3d2c;color:var(--green);border-color:#445942}.fixture-list{display:grid;gap:8px}.match-row{display:grid;grid-template-columns:110px 1fr 110px 65px;align-items:center;gap:12px;border:1px solid var(--line);background:var(--panel);border-radius:10px;padding:12px}.match-date{font-size:10px;color:var(--muted)}.match-opponent{text-align:center;font-weight:600;font-size:12px}.match-opponent span{color:#859187;font-weight:400;padding:0 8px}.match-score{text-align:center;font-weight:700}.match-status{text-align:right;font-size:10px;color:var(--muted)}.competition-cards{grid-template-columns:repeat(3,1fr)}.competition-card{min-height:145px;position:relative;overflow:hidden}.competition-card .comp-icon{font-size:26px}.competition-card h3{font:600 15px 'Space Grotesk';margin:12px 0 5px}.competition-card p{color:var(--muted);font-size:11px;line-height:1.5;margin:0}.competition-card .comp-badge{position:absolute;right:15px;top:15px}.standings-note{color:var(--muted);font-size:11px;line-height:1.6}.empty-note{padding:22px;text-align:center;color:var(--muted);font-size:12px}.toast{position:fixed;bottom:23px;left:50%;transform:translate(-50%,20px);background:#e2ffc5;color:#182116;padding:12px 17px;border-radius:9px;font-weight:700;font-size:12px;box-shadow:0 12px 35px #0008;opacity:0;pointer-events:none;transition:.25s;z-index:20}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#080b09d9;z-index:10;display:grid;place-items:center;padding:20px}.modal{width:min(490px,100%);background:#1b231d;border:1px solid #354337;border-radius:16px;padding:25px;box-shadow:0 24px 80px #0008}.modal h2{font:600 21px 'Space Grotesk';margin:0 0 5px}.modal p{color:var(--muted);font-size:12px;line-height:1.5;margin:0 0 18px}.club-options{display:grid;grid-template-columns:1fr 1fr;gap:9px}.club-option{padding:12px;background:#202a22;border:1px solid var(--line);border-radius:10px;color:var(--text);text-align:left}.club-option:hover{border-color:var(--green)}.club-option strong{display:block;margin-bottom:4px}.club-option small{color:var(--muted)}.modal-foot{margin-top:16px;color:#78867a;font-size:10px}.toast-error{background:#ffe0dc;color:#511e1e}.mobile-menu{display:none}
@media(max-width:1000px){.app-shell{grid-template-columns:205px minmax(0,1fr)}.main{padding:24px}.overview-grid{grid-template-columns:1fr}.fixture-card{min-height:220px}.lower-grid{grid-template-columns:1fr}.market-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:680px){.app-shell{display:block}.sidebar{position:fixed;z-index:5;height:auto;width:100%;top:auto;bottom:0;left:0;padding:8px 6px calc(8px + env(safe-area-inset-bottom));border:0;border-top:1px solid var(--line);background:#141a15}.brand,.side-label,.side-bottom{display:none}.nav{display:flex;justify-content:space-around;gap:2px}.nav button{display:flex;flex-direction:column;gap:3px;text-align:center;padding:7px 5px;font-size:9px;border-radius:8px;flex:1}.nav button.active{box-shadow:inset 0 2px var(--green)}.nav-icon{font-size:16px}.main{padding:19px 15px 100px}.topbar{margin-bottom:20px}.topbar h1{font-size:21px}.season-pill{padding:0 8px;font-size:10px}.top-actions{gap:6px}.icon-btn{width:34px;height:34px}.avatar{height:32px;width:32px}.overview-grid{gap:12px}.hero-card{padding:19px;min-height:225px}.hero-stats{gap:22px}.hero-stat strong{font-size:18px}.lower-grid{gap:12px}.card{padding:15px}.section-grid{grid-template-columns:1fr}.market-grid{grid-template-columns:1fr 1fr;gap:9px}.market-card{padding:12px}.market-face{width:39px;height:39px;font-size:19px}.market-person{gap:8px}.market-name{font-size:12px}.market-info{font-size:10px}.competition-cards{grid-template-columns:1fr}.player-row{grid-template-columns:34px minmax(90px,1fr) 35px 52px;gap:8px;padding:10px}.player-row .player-value{display:none}.match-row{grid-template-columns:68px 1fr 48px;gap:7px;padding:11px 8px}.match-status{display:none}.match-date{font-size:9px}.match-opponent{font-size:10px}.match-opponent span{padding:0 3px}.table th,.table td{padding:9px 4px;font-size:10px}.table th{font-size:9px}.form-dots .dot:nth-child(-n+2){display:none}.view-toolbar{align-items:flex-start;flex-direction:column}.fixture-teams{margin:14px 0}.club-title{font-size:21px}.toast{width:max-content;max-width:90vw}}

const LEAGUES={
  England:{name:'Premier League',clubs:[['Arsenal','🔴',84],['Liverpool','🔺',86],['Manchester City','🔷',89],['Chelsea','🔵',81],['Tottenham','⚪',79],['Newcastle','⚫',78],['Aston Villa','🟣',77],['Manchester United','🔴',80]]},
  Spain:{name:'La Liga',clubs:[['Real Madrid','👑',90],['Barcelona','🔵',88],['Atlético Madrid','🔴',84],['Athletic Club','🦁',78],['Real Sociedad','🔵',77],['Villarreal','🟡',76],['Sevilla','⚪',75],['Real Betis','🟢',76]]},
  Germany:{name:'Bundesliga',clubs:[['Bayern Munich','🔴',89],['Borussia Dortmund','🟡',84],['Bayer Leverkusen','🔴',85],['RB Leipzig','🔴',82],['Eintracht Frankfurt','🦅',78],['Stuttgart','🔴',78],['Wolfsburg','🟢',75],['Freiburg','⚫',74]]},
  Italy:{name:'Serie A',clubs:[['Inter Milan','🔵',87],['AC Milan','🔴',84],['Juventus','⚪',84],['Napoli','🔵',83],['Roma','🟡',79],['Atalanta','🔵',81],['Lazio','🦅',78],['Fiorentina','🟣',77]]},
  France:{name:'Ligue 1',clubs:[['Paris Saint-Germain','🔵',88],['Monaco','🔴',80],['Marseille','⚪',79],['Lille','🔴',78],['Lyon','🔵',77],['Nice','⚫',76],['Lens','🟡',75],['Rennes','🔴',75]]},
  Portugal:{name:'Primeira Liga',clubs:[['Benfica','🔴',83],['Porto','🔵',83],['Sporting CP','🟢',82],['Braga','🔴',76],['Vitória SC','⚫',73],['Boavista','⚫',69],['Famalicão','🔵',70],['Casa Pia','⚫',68]]}
};
const PLAYERS=[
 {name:'Kylian Mbappé',pos:'ST',rating:92,value:180,country:'France',face:'⚡'}, {name:'Erling Haaland',pos:'ST',rating:91,value:165,country:'Norway',face:'👑'},
 {name:'Jude Bellingham',pos:'CM',rating:90,value:145,country:'England',face:'✨'}, {name:'Vinícius Júnior',pos:'LW',rating:90,value:150,country:'Brazil',face:'💫'},
 {name:'Mohamed Salah',pos:'RW',rating:89,value:75,country:'Egypt',face:'⚡'}, {name:'Kevin De Bruyne',pos:'CM',rating:89,value:55,country:'Belgium',face:'🎯'},
 {name:'Lamine Yamal',pos:'RW',rating:88,value:120,country:'Spain',face:'🌟'}, {name:'Harry Kane',pos:'ST',rating:89,value:95,country:'England',face:'🎯'},
 {name:'Declan Rice',pos:'DM',rating:87,value:95,country:'England',face:'🛡️'}, {name:'Rodri',pos:'DM',rating:90,value:110,country:'Spain',face:'🧠'},
 {name:'Bukayo Saka',pos:'RW',rating:88,value:130,country:'England',face:'💨'}, {name:'Pedri',pos:'CM',rating:87,value:100,country:'Spain',face:'🎩'},
 {name:'Lautaro Martínez',pos:'ST',rating:88,value:100,country:'Argentina',face:'🔥'}, {name:'Victor Osimhen',pos:'ST',rating:87,value:90,country:'Nigeria',face:'💪'},
 {name:'Rafael Leão',pos:'LW',rating:87,value:95,country:'Portugal',face:'⚡'}, {name:'Federico Valverde',pos:'CM',rating:88,value:110,country:'Uruguay',face:'🏃'},
 {name:'Virgil van Dijk',pos:'CB',rating:88,value:45,country:'Netherlands',face:'🧱'}, {name:'Alisson Becker',pos:'GK',rating:89,value:45,country:'Brazil',face:'🧤'},
 {name:'Jamal Musiala',pos:'AM',rating:88,value:110,country:'Germany',face:'✨'}, {name:'Bruno Fernandes',pos:'AM',rating:87,value:70,country:'Portugal',face:'🎯'}
];
const START_SQUAD=[['A. Keeper','GK',79],['R. Defender','RB',78],['M. Centre-back','CB',81],['L. Centre-back','CB',80],['J. Fullback','LB',77],['D. Midfielder','DM',82],['T. Playmaker','CM',83],['A. Winger','RW',84],['S. Forward','ST',85],['M. Striker','ST',82],['C. Winger','LW',81],['B. Keeper','GK',73],['P. Defender','CB',75],['N. Midfielder','CM',76],['E. Forward','ST',77]];
const KEY='touchline-career-v1';
let state=loadState(); let marketFilter='All';
function loadState(){try{return JSON.parse(localStorage.getItem(KEY))}catch{return null}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function clubData(name){for(const [country,l] of Object.entries(LEAGUES)){const c=l.clubs.find(x=>x[0]===name);if(c)return {country,league:l.name,crest:c[1],rating:c[2],clubs:l.clubs}}}
function initialState(name){const c=clubData(name);return {club:name,country:c.country,league:c.league,crest:c.crest,rating:c.rating,budget:c.rating>=85?125:95,week:0,euroPlayed:0,euroType:['Arsenal','Liverpool','Manchester City','Real Madrid','Barcelona','Atlético Madrid','Bayern Munich','Borussia Dortmund','Bayer Leverkusen','Inter Milan','AC Milan','Juventus','Paris Saint-Germain','Benfica','Porto','Sporting CP'].includes(name)?'Champions League':'Conference League',squad:START_SQUAD.map(([name,pos,rating],i)=>({name,pos,rating:Math.min(94,rating+Math.floor((c.rating-80)/3)),value:Math.max(3,Math.round((rating-60)*1.5)),face:['🧤','🛡️','🧱','🧱','🛡️','🧠','🎯','💨','⚽','⚽','💨'][i%11]})),bought:[],log:[],results:[],euroResults:[],table:{},euroPoints:0,euroWins:0,formation:'4-3-3',season:1};}
function ensureState(){if(!state||!clubData(state.club)){state=null;return}const clubs=clubData(state.club).clubs;clubs.forEach(([name,crest,rating],i)=>{if(!state.table[name])state.table[name]={name,crest,rating,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0,form:[]}});}
if(state)ensureState();
const app=document.getElementById('app');
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(n){return '€'+n+'m'}
function toast(msg,error=false){const el=document.querySelector('.toast');if(!el)return;el.textContent=msg;el.classList.toggle('toast-error',error);el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2500)}
function navButton(id,icon,label){return `<button class="${activeView===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`}
let activeView='overview';
function render(){if(!state){renderWelcome();return}ensureState();app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">✦</div><div class="brand-name">touch<span>line</span></div></div><div class="side-label">Manager's office</div><nav class="nav">${navButton('overview','◫','Overview')}${navButton('squad','♙','Squad')}${navButton('transfers','⇄','Transfers')}${navButton('fixtures','▦','Fixtures')}${navButton('table','▤','League table')}${navButton('europe','✦','Europe')}</nav><div class="side-bottom"><div class="side-label">Your club</div><div class="club-mini"><div class="club-mini-top"><div class="club-badge">${state.crest}</div><div><strong>${esc(state.club)}</strong><small>${esc(state.league)}</small></div></div></div></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">${esc(state.league)} · Season ${state.season}</div><h1 id="page-title">${pageTitle()}</h1></div><div class="top-actions"><div class="season-pill">${money(state.budget)} <span style="color:var(--muted)">budget</span></div><button class="icon-btn" id="reset-btn" title="New career">↻</button><div class="avatar">${state.crest}</div></div></header><section class="view ${activeView==='overview'?'active':''}" id="overview-view">${overviewView()}</section><section class="view ${activeView==='squad'?'active':''}" id="squad-view">${squadView()}</section><section class="view ${activeView==='transfers'?'active':''}" id="transfers-view">${transfersView()}</section><section class="view ${activeView==='fixtures'?'active':''}" id="fixtures-view">${fixturesView()}</section><section class="view ${activeView==='table'?'active':''}" id="table-view">${tableView()}</section><section class="view ${activeView==='europe'?'active':''}" id="europe-view">${europeView()}</section></main></div><div class="toast"></div>`;bind();}
function pageTitle(){return ({overview:'Club overview',squad:'First team',transfers:'Transfer market',fixtures:'Fixtures & results',table:'League standings',europe:'European nights'})[activeView]}
function renderWelcome(){app.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="brand" style="padding:0 0 17px"><div class="brand-mark">✦</div><div class="brand-name">touch<span>line</span></div></div><h2>Every great story starts here.</h2><p>Choose your club. Build your squad, make the big calls, and chase glory across Europe.</p><div class="club-options">${Object.entries(LEAGUES).map(([country,l])=>{const [name,crest,rating]=l.clubs[0];return `<button class="club-option" data-start="${esc(name)}"><strong>${crest} ${esc(name)}</strong><small>${country} · ${l.name}</small></button>`}).join('')}</div><div class="modal-foot">Six leagues. Real clubs. Your legacy.</div></div></div>`;document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{state=initialState(b.dataset.start);save();activeView='overview';render()})}

function sortedTable(){return Object.values(state.table).sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function tableMarkup(rows,limit){return `<table class="table"><thead><tr><th>#</th><th>Club</th><th>P</th><th>W</th><th>D</th><th>L</th><th>GD</th><th>Pts</th></tr></thead><tbody>${rows.slice(0,limit||rows.length).map((r,i)=>`<tr class="${r.name===state.club?'you-row':''}"><td class="pos">${i+1}</td><td><span class="club-cell"><span class="mini-crest">${r.crest}</span>${esc(r.name)}</span></td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf-r.ga>0?'+':''}${r.gf-r.ga}</td><td class="points">${r.pts}</td></tr>`).join('')}</tbody></table>`}
function upcomingOpponent(){const clubs=clubData(state.club).clubs.filter(c=>c[0]!==state.club);return clubs[(state.week*3+1)%clubs.length]}
function latestResult(){return state.results[state.results.length-1]}
function overviewView(){const t=state.table[state.club],rank=sortedTable().findIndex(r=>r.name===state.club)+1,op=upcomingOpponent(),played=state.week;return `<div class="grid overview-grid"><article class="card hero-card"><div class="hero-head"><div><div class="club-overline">${esc(state.country)} · ${esc(state.league)}</div><h2 class="club-title">${esc(state.club)}</h2><div class="club-subtitle">Your club. Your decisions. Your era.</div></div><div class="rank-chip">${ordinal(rank)} in league</div></div><div class="hero-stats"><div class="hero-stat"><small>League points</small><strong>${t.pts} <em>PTS</em></strong></div><div class="hero-stat"><small>Matches played</small><strong>${t.p} <em>/ 14</em></strong></div><div class="hero-stat"><small>Transfer budget</small><strong>${money(state.budget)}</strong></div></div></article><article class="card fixture-card"><div><div class="card-heading"><h2>Next match</h2><span class="fixture-type">${played%4===3?'European night':state.league}</span></div><div class="fixture-teams"><div class="team-side"><span class="team-crest">${state.crest}</span><strong>${esc(state.club)}</strong></div><div class="vs">VS</div><div class="team-side"><span class="team-crest">${op[1]}</span><strong>${esc(op[0])}</strong></div></div><div class="fixture-meta"><span>Matchday ${Math.floor(played*3/4)+1} · ${played%4===3?'Continental Cup':'League'}</span><span>Today · 20:00</span></div></div><button class="primary-btn" id="play-match">▶ &nbsp; Play next match</button></article></div><div class="grid lower-grid"><article class="card"><div class="card-heading"><h2>League table</h2><button class="text-btn" data-view="table">Full table →</button></div>${tableMarkup(sortedTable(),5)}</article><article class="card"><div class="card-heading"><h2>Manager's inbox</h2><button class="text-btn" data-view="fixtures">All activity</button></div><div class="activity-list">${activityMarkup()}</div></article></div>`}
function ordinal(n){return n+(['st','nd','rd'][((n+90)%100-10)%10-1]||'th')}
function activityMarkup(){let logs=state.log.slice(-3).reverse();if(!logs.length)logs=[`Welcome to ${state.club}. The board is backing you to make this a season to remember.`];return logs.map((x,i)=>`<div class="activity"><div class="activity-icon">${i===0?'✦':'◷'}</div><div class="activity-text">${x}<small>${i===0?'Just now':`${i+1} weeks ago`}</small></div></div>`).join('')}
function squadView(){return `<div class="grid section-grid"><article class="card"><div class="card-heading"><h2>Senior squad <span style="color:var(--muted);font:400 11px 'DM Sans'">· ${state.squad.length} players</span></h2><span class="tag">${state.formation}</span></div><div class="squad-list">${state.squad.map(p=>`<div class="player-row"><div class="player-avatar">${p.face||'⚽'}</div><div><div class="player-name">${esc(p.name)}</div><div class="player-meta"><span class="position-label">${p.pos}</span> · ${p.age||24} yrs</div></div><div class="rating">${p.rating}</div><span class="tag">${p.pos}</span><div class="player-value">${money(p.value)}</div></div>`).join('')}</div></article><aside class="card"><div class="card-heading"><h2>Squad report</h2></div><div class="hero-stat" style="margin-bottom:18px"><small>Squad rating</small><strong>${Math.round(state.squad.reduce((a,p)=>a+p.rating,0)/state.squad.length)} <em>AVG</em></strong></div><div class="activity-list"><div class="activity"><div class="activity-icon">⚽</div><div class="activity-text"><strong>${state.squad.filter(p=>p.pos==='ST').length} forwards</strong><small>Attack options</small></div></div><div class="activity"><div class="activity-icon">🛡</div><div class="activity-text"><strong>${state.squad.filter(p=>['CB','LB','RB','GK'].includes(p.pos)).length} defenders</strong><small>Back line depth</small></div></div><div class="activity"><div class="activity-icon">💶</div><div class="activity-text"><strong>${money(state.budget)} remaining</strong><small>Available transfer budget</small></div></div></div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><div class="card-heading"><h2>Manager's note</h2></div><div class="standings-note">Make signings in the transfer market to strengthen your starting XI. Players you buy join the squad immediately.</div><button class="secondary-btn" data-view="transfers" style="width:100%;margin-top:15px">Browse transfer market →</button></aside></div>`}
function transfersView(){const bought=new Set(state.bought);const list=PLAYERS.filter(p=>marketFilter==='All'||p.pos===marketFilter);return `<div class="view-toolbar"><div><h2>Make your move</h2><div class="eyebrow" style="margin-top:5px">Sign world-class talent to take your club to the top.</div></div><div class="season-pill">Available: <strong style="color:var(--green)">${money(state.budget)}</strong></div></div><div class="filter-tabs" style="margin-bottom:16px">${['All','ST','Winger','CM','DM','CB','GK'].map(f=>`<button class="${marketFilter===f?'active':''}" data-filter="${f}">${f==='All'?'All players':f==='ST'?'Strikers':f==='Winger'?'Wingers':f==='CM'?'Midfielders':f==='DM'?'Defensive mid':f==='CB'?'Defenders':'Goalkeepers'}</button>`).join('')}</div><div class="grid market-grid">${list.map(p=>`<article class="card market-card"><div class="market-person"><div class="market-face">${p.face}</div><div><div class="market-name">${esc(p.name)}</div><div class="market-info">${p.pos} · ${p.country}</div></div></div><div class="market-stats"><span>Rating <strong>${p.rating}</strong></span><span>Market value <strong>${money(p.value)}</strong></span></div><button class="primary-btn sign-btn" data-player="${esc(p.name)}" ${bought.has(p.name)||state.budget<p.value?'disabled':''}>${bought.has(p.name)?'✓ Signed':state.budget<p.value?'Not enough funds':`Sign · ${money(p.value)}`}</button></article>`).join('')}</div>`}

function fixturesView(){const clubs=clubData(state.club).clubs.filter(c=>c[0]!==state.club);let rows=[];for(let i=0;i<Math.max(8,state.week+4);i++){if(i<state.results.length){const r=state.results[i];rows.push(`<div class="match-row"><div class="match-date">Matchday ${i+1}</div><div class="match-opponent">${r.home?esc(state.club):esc(r.opponent)} <span>${r.home?'vs':'@'}</span> ${r.home?esc(r.opponent):esc(state.club)}</div><div class="match-score">${r.home?r.gf+' – '+r.ga:r.ga+' – '+r.gf}</div><div class="match-status">${r.comp}</div></div>`)}else{let op=clubs[(i*3+1)%clubs.length];rows.push(`<div class="match-row"><div class="match-date">Matchday ${i+1}</div><div class="match-opponent">${i%4===3?'✦ ':''}${esc(state.club)} <span>vs</span> ${op[1]} ${esc(op[0])}</div><div class="match-score">— : —</div><div class="match-status">${i%4===3?'Europe':'Upcoming'}</div></div>`)}}return `<div class="view-toolbar"><h2>Season schedule</h2><span class="season-pill">Matchday ${state.week+1} of 14</span></div><div class="fixture-list">${rows.join('')}</div>`}
function tableView(){return `<div class="view-toolbar"><h2>${esc(state.league)} · Season ${state.season}</h2><span class="season-pill">${state.week} matches played</span></div><div class="card">${tableMarkup(sortedTable())}<p class="standings-note">Top 4 qualify for European competition. Your club's position is highlighted. Win matches to climb the table.</p></div>`}
function europeView(){const comp=state.euroType,other=comp==='Champions League'?'Conference League':'Champions League';const cups=[['🏆','Champions League','Europe’s biggest stage · 36 clubs','⭐'],['🌟','Conference League','A new route to European glory','✦'],['🏟️','Domestic league',state.league+' · 8 clubs','🏠']];return `<div class="grid competition-cards" style="margin-bottom:17px">${cups.map(c=>`<article class="card competition-card"><span class="comp-icon">${c[0]}</span><span class="comp-badge">${c[3]}</span><h3>${c[1]}</h3><p>${c[2]}</p></article>`).join('')}</div><div class="grid section-grid"><article class="card"><div class="card-heading"><h2>${esc(comp)} · League phase</h2><span class="tag">${state.euroPlayed>=8?'Completed':`${Math.min(8,state.euroPlayed+1)} / 8`}</span></div><p class="standings-note">Your club is competing in the ${comp}. European fixtures arrive every fourth matchday. Finish in the top 8 to advance automatically.</p><div style="margin-top:16px">${euroTableMarkup()}</div></article><aside class="card"><div class="card-heading"><h2>European campaign</h2></div><div class="hero-stat" style="margin-bottom:17px"><small>Competition</small><strong style="font-size:17px">${comp}</strong></div><div class="hero-stat" style="margin-bottom:14px"><small>Points earned</small><strong>${state.euroPoints} <em>PTS</em></strong></div><div class="activity-text">${state.euroPlayed?`${state.euroWins} wins from ${state.euroPlayed} European matches.`:'Your European adventure starts on matchday 4.'}<small>Next continental fixture: ${Math.max(0,4-(state.week%4))} matchday${4-(state.week%4)===1?'':'s'} away</small></div></aside></div>`}
function euroTableMarkup(){const data=state.euroResults.reduce((a,r)=>{if(!a[r.opponent])a[r.opponent]={name:r.opponent,crest:r.crest||'⚽',p:0,pts:0};a[r.opponent].p++;a[r.opponent].pts+=r.result==='W'?3:r.result==='D'?1:0;return a},{});data[state.club]={name:state.club,crest:state.crest,p:state.euroPlayed,pts:state.euroPoints};let rows=Object.values(data).sort((a,b)=>b.pts-a.pts);if(!rows.length)rows=[{name:state.club,crest:state.crest,p:0,pts:0}];return `<table class="table"><thead><tr><th>#</th><th>Club</th><th>P</th><th>Pts</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.name===state.club?'you-row':''}"><td class="pos">${i+1}</td><td><span class="club-cell"><span class="mini-crest">${r.crest}</span>${esc(r.name)}</span></td><td>${r.p}</td><td class="points">${r.pts}</td></tr>`).join('')}</tbody></table>`}
function playMatch(){const isEuro=state.week%4===3;const op=upcomingOpponent();let myAttack=state.squad.filter(p=>['ST','LW','RW','AM'].includes(p.pos)).reduce((a,p)=>a+p.rating,0)/Math.max(1,state.squad.filter(p=>['ST','LW','RW','AM'].includes(p.pos)).length);let myDef=state.squad.filter(p=>['GK','CB','LB','RB','DM'].includes(p.pos)).reduce((a,p)=>a+p.rating,0)/Math.max(1,state.squad.filter(p=>['GK','CB','LB','RB','DM'].includes(p.pos)).length);let strength=(myAttack+myDef)/2;let diff=(strength-op[2])/7;let myGoals=goals(Math.max(.45,1.35+diff*.28)),theirGoals=goals(Math.max(.35,1.1-diff*.22));const home=Math.random()>.43;if(!home)[myGoals,theirGoals]=[theirGoals,myGoals];let comp=isEuro?state.euroType:state.league;let opponent=op[0];let result=myGoals>theirGoals?'W':myGoals===theirGoals?'D':'L';let log;if(!isEuro){const t=state.table[state.club],ot=state.table[opponent];t.p++;ot.p++;t.gf+=home?myGoals:theirGoals;t.ga+=home?theirGoals:myGoals;ot.gf+=home?theirGoals:myGoals;ot.ga+=home?myGoals:theirGoals;if(result==='W'){t.w++;t.pts+=3;ot.l++}else if(result==='L'){t.l++;ot.w++;ot.pts+=3}else{t.d++;ot.d++;t.pts++;ot.pts++}t.form.push(result);ot.form.push(result==='W'?'L':result==='L'?'W':'D');t.form=t.form.slice(-5);ot.form=ot.form.slice(-5);log=`${result==='W'?'<strong>Big win!</strong>':result==='D'?'A hard-fought draw.':'<strong>Tough result.</strong>'} ${esc(state.club)} ${home?myGoals+'–'+theirGoals:theirGoals+'–'+myGoals} ${esc(opponent)} in ${state.league}.`;state.results.push({opponent,gf:myGoals,ga:theirGoals,home,comp,result})}else{state.euroPlayed++;state.euroPoints+=result==='W'?3:result==='D'?1:0;if(result==='W')state.euroWins++;state.euroResults.push({opponent,crest:op[1],gf:myGoals,ga:theirGoals,result});log=`<strong>European night:</strong> ${esc(state.club)} ${home?myGoals+'–'+theirGoals:theirGoals+'–'+myGoals} ${esc(opponent)} in the ${comp}.`;state.results.push({opponent,gf:myGoals,ga:theirGoals,home,comp,result})}state.week++;if(state.week>=14){finishSeason();}state.log.push(log);state.log=state.log.slice(-12);save();render();const r=state.results[state.results.length-1];toast(`${r.result==='W'?'Victory!':r.result==='D'?'Full time — a draw.':'Full time — defeat.'} ${state.club} ${r.home?r.gf+'–'+r.ga:r.ga+'–'+r.gf} ${r.opponent}`)}
function goals(lambda){let sum=0,p=1,L=Math.exp(-lambda);do{sum++;p*=Math.random()}while(p>L);return sum-1}
function finishSeason(){let rank=sortedTable().findIndex(r=>r.name===state.club)+1;let prize=rank===1?45:rank<=4?25:10;state.budget+=prize;state.log.push(rank===1?`<strong>Champions!</strong> ${state.club} have won the ${state.league}. The board awards a ${money(prize)} bonus!`:`Season complete: ${ordinal(rank)} in ${state.league}. The board adds ${money(prize)} to the transfer kitty.`);state.season++;state.week=0;state.euroPlayed=0;state.euroPoints=0;state.euroWins=0;state.euroResults=[];state.results=[];for(const row of Object.values(state.table)){row.p=0;row.w=0;row.d=0;row.l=0;row.gf=0;row.ga=0;row.pts=0;row.form=[]}if(rank===1)state.euroType='Champions League';else if(rank<=4&&state.euroType==='Conference League')state.euroType='Champions League'}

function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{activeView=b.dataset.view;render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{marketFilter=b.dataset.filter;render()});document.querySelectorAll('.sign-btn').forEach(b=>b.onclick=()=>buyPlayer(b.dataset.player));let play=document.getElementById('play-match');if(play)play.onclick=playMatch;let reset=document.getElementById('reset-btn');if(reset)reset.onclick=()=>{if(confirm('Start a new career? Your current save will be replaced.')){state=null;localStorage.removeItem(KEY);render()}}}
function buyPlayer(name){const p=PLAYERS.find(x=>x.name===name);if(!p||state.bought.includes(name))return;if(state.budget<p.value){toast('Not enough transfer funds.',true);return}state.budget-=p.value;state.bought.push(name);state.squad.push({name:p.name,pos:p.pos,rating:p.rating,value:p.value,face:p.face,age:26});state.log.push(`<strong>Signing complete:</strong> ${esc(p.name)} joins ${esc(state.club)} for ${money(p.value)}.`);state.log=state.log.slice(-12);save();render();toast(`${p.name} signed! Welcome to ${state.club}.`)}
render();

