            <td><span class="club-cell"><span class="mini-crest">${row.badge}</span>${escapeHtml(row.name)}</span></td>
            <td>${row.played}</td>
            <td>${row.wins}</td>
            <td>${row.draws}</td>
            <td>${row.losses}</td>
            <td>${(row.gf - row.ga) >= 0 ? '+' : ''}${row.gf - row.ga}</td>
            <td class="points">${row.pts}</td>
