845: function generateGoals(teamPower, opponentPower) {
846:   const difference = teamPower - opponentPower;
847:   let goals = 0;
848: 
849:   if (difference > 10) {
850:     goals = 2 + (Math.random() > 0.55 ? 1 : 0) + (Math.random() > 0.75 ? 1 : 0);
851:   } else if (difference > 3) {
852:     goals = 1 + (Math.random() > 0.68 ? 1 : 0) + (Math.random() > 0.88 ? 1 : 0);
853:   } else if (difference > -3) {
854:     goals = Math.round(Math.random() * 2) + 1;
855:   } else if (difference > -10) {
856:     goals = Math.round(Math.random() * 2);
857:   } else {
858:     goals = Math.round(Math.random() * 1);
859:   }
860: 
861:   return Math.max(0, Math.min(5, goals));
862: }
