864: function updateLeagueTable(teamName, opponentName, myGoals, oppGoals) {
865:   const team = state.table[teamName];
866:   const opponent = state.table[opponentName];
867: 
868:   if (!team || !opponent) {
869:     return;
870:   }
871: 
872:   team.played += 1;
873:   opponent.played += 1;
874:   team.gf += myGoals;
875:   team.ga += oppGoals;
876:   opponent.gf += oppGoals;
877:   opponent.ga += myGoals;
878: 
879:   if (myGoals > oppGoals) {
880:     team.wins += 1;
881:     team.pts += 3;
882:     opponent.losses += 1;
883:     team.form.push('W');
884:     opponent.form.push('L');
885:   } else if (myGoals < oppGoals) {
886:     team.losses += 1;
887:     opponent.wins += 1;
888:     opponent.pts += 3;
889:     team.form.push('L');
890:     opponent.form.push('W');
891:   } else {
892:     team.draws += 1;
893:     opponent.draws += 1;
894:     team.pts += 1;
895:     opponent.pts += 1;
896:     team.form.push('D');
897:     opponent.form.push('D');
898:   }
899: 
900:   team.form = team.form.slice(-5);
901:   opponent.form = opponent.form.slice(-5);
902: }
