904: function playMatch() {
905:   const leagueNames = getLeagueClubNames();
906:   const opponentName = getNextLeagueOpponent();
907:   const isEuropean = state.week % 4 === 3;
908:   const teamStrength = getOverallStrength();
909:   const opponentStrength = getClubStrength(opponentName);
910:   const myGoals = generateGoals(teamStrength, opponentStrength);
911:   const oppGoals = generateGoals(opponentStrength, teamStrength);
912: 
913:   const home = Math.random() > 0.45;
914:   const myScore = home ? myGoals : oppGoals;
915:   const oppScore = home ? oppGoals : myGoals;
916:   const result = myScore > oppScore ? 'W' : myScore === oppScore ? 'D' : 'L';
917: 
918:   if (isEuropean) {
919:     const euroList = state.euroCompetition === 'Champions League' ? CHAMPIONS_CLUBS : CONFERENCE_CLUBS;
920:     const euroOpponent = euroList[(state.euroMatches + Math.floor(state.week / 4)) % euroList.length] || state.club;
921:     state.euroMatches += 1;
922:     if (result === 'W') state.euroWins += 1;
923:     if (result === 'W') state.euroPoints += 3;
924:     if (result === 'D') state.euroPoints += 1;
925:     state.euroResults.push({ opponent: euroOpponent, badge: getBadgeForClub(euroOpponent), result, gf: myScore, ga: oppScore });
926:     state.results.push({ opponent: euroOpponent, gf: myScore, ga: oppScore, home, comp: state.euroCompetition, result });
927:     state.log.push(`<strong>European night:</strong> ${escapeHtml(state.club)} ${myScore}-${oppScore} ${escapeHtml(euroOpponent)} in the ${state.euroCompetition}.`);
928:   } else {
