931:     state.log.push(`<strong>${result === 'W' ? 'Victory' : result === 'D' ? 'Draw' : 'Defeat'}</strong> ${escapeHtml(state.club)} ${myScore}-${oppScore} ${escapeHtml(opponentName)} in ${escapeHtml(state.league)}.`);
